/bin/bash -lc "node --input-type=module -e '
const base = \"http://127.0.0.1:3100\";
const checks = [];
async function check(name, path, expectedStatus, init, includes) {
  const response = await fetch(base + path, init);
  const body = await response.text();
  if (response.status "'!== expectedStatus || (includes && !body.includes(includes))) {
    throw new Error(name + " failed: status=" + response.status + " body=" + body.slice(0, 160));
  }
  checks.push(name + ":" + response.status);
  return { response, body };
}
await check("home", "/", 200, { headers: { "user-agent": "app-router-smoke-test" } }, "app-router-smoke-test");
await check("blog", "/blog", 200, undefined, "All Blog Posts");
await check("blog post", "/blog/1", 200, undefined, "Comments (5)");
await check("not found", "/missing-route", 404, undefined, "404 - Page Not Found");
await check("posts list", "/api/posts", 200, undefined, "First Post");
await check("posts validation", "/api/posts", 400, { method: "POST", headers: { "content-type": "application/json" }, body: "{}" }, "Title and content are required");
await check("post create", "/api/posts", 201, { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ title: "Typed", content: "Route" }) }, "createdAt");
await check("post detail", "/api/posts/7", 200, undefined, "Post 7");
await check("post update", "/api/posts/7", 200, { method: "PUT", headers: { "content-type": "application/json" }, body: JSON.stringify({ title: "Updated" }) }, "updatedAt");
await check("post delete", "/api/posts/7", 200, { method: "DELETE" }, "deleted successfully");
const rejected = await check("method rejected", "/api/posts", 405, { method: "PATCH" }, "Method PATCH Not Allowed");
if (rejected.response.headers.get("allow") !== "GET, POST") throw new Error("Allow header mismatch");
console.log(checks.join("'"\\n\"));
'"

